contracts/01_BimboGummy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";
import "./02_Receipt.sol";

contract BimboGummy is ERC20, ERC20Permit {

    Receipt private receipt;

    mapping(address => mapping (address => uint8)) private _blackList;

    event ReceiptIssued(
        address indexed from,
        address indexed to,
        uint256 amount,
        uint256 receiptTokenId,
        bytes32 txHash
    );


    constructor(address _receiptNFT) ERC20("BimboGummy", "BBGM") ERC20Permit("BimboGummy") {
        //_mint(msg.sender, 1000 * 10 ** decimals());
        require(_receiptNFT != address(0), "Invalid NFT address");
        receipt = Receipt(_receiptNFT);
    }

    event MintBimboGummy(uint256 count);

    event DebugEvent(string text);    


    //function allowance(address owner, address spender) public virtual override returns (uint256){}



    function Mint (uint256 count) public payable {
        _mint(msg.sender, count);
        emit MintBimboGummy(count);
    }

    //used for DirectAttack
    function transfer (address to, uint256 amount) public virtual override returns (bool) {
        address owner = _msgSender();
        uint256 _amount = amount;
        if (_amount < 1 ){
            _amount = 1;
        }
        //足りなかったら送れない
        require(balanceOf(owner) >= _amount, "Insufficient balance.");
        //相手のブラックリストに自分が入っている場合も失敗
        require(_blackList[owner][to] == 0, "the tartget address is blacklisted.;");
        require(_blackList[to][owner] == 0, "the owner address is blacklisted.;");

        //Burn禁止
        require(to != address(0), "Burn is forbidden.;");

        bool success = super.transfer(to,_amount);
        if (success) {
            _mintReceipt(owner,to,1,true);//攻撃者に青レシートを付与
            _mintReceipt(owner,to,1,false);//標的に赤レシートを付与
            _blackList[owner][to] = 1;
            _blackList[to][owner] = 2;
        }
        return success;
    }



    function transferFrom(address from, address to, uint256 amount) public virtual override returns (bool) {
        //_;
        bool success = super.transferFrom(from, to, amount);
        if (success) {
            _mintReceipt(from, to, 1,true);
            _mintReceipt(from,to,1,false);
        }
        return success;
    }

    function getBlackList(address from , address to) public view returns (uint8,uint8) {

        return (_blackList[from][to],_blackList[to][from]);

    }

    function _mintReceipt(address from, address to, uint256 amount,bool isBlueReceipt) internal {

        uint256 balanceOfFrom = balanceOf(from);
        uint256 balanceOfTo = balanceOf(to);

        bytes32 pseudoTxHash = keccak256(
            abi.encodePacked(from, to, amount, block.timestamp)
        );//各項目をつなげた文字列をbytesに変換してさらにそれを元に256ビットのハッシュ値を作る
        address recipient = from;
        if(!isBlueReceipt){
            recipient = to;
        }
        uint256 receiptTokenId = receipt.mint(//ここでReceiptを発行
            recipient,  // NFT を受け取るのはトークン送信者
            from,
            to,
            amount,
            balanceOfFrom,
            balanceOfTo,
            pseudoTxHash,
            isBlueReceipt
        );

        emit ReceiptIssued(from, to, amount, receiptTokenId, pseudoTxHash);
    }

    //以下の関数はRanking.solに移管したのでそのうち消す

    //指定したユーザーが持ってるレシートの量を取得する
    function receiptBalanceOf(address user) public view returns (uint256) {
        return receipt.balanceOf(user); // ✅ 問題なく動作する
    }

    //指定したユーザーが持っているレシートの中から、{tokenId}番目の情報を取得する
    function receiptTokenOfOwnerByIndex(address owner, uint256 tokenId) public view returns (uint256) {
        return receipt.tokenOfOwnerByIndex(owner,tokenId); // ✅ 問題なく動作する
    }


}

contracts/02_Receipt.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "./03_Ranking.sol";

contract Receipt is ERC721Enumerable {

  //本当の通信記録はこっちに残す
  struct TransferRecord {
    address from;
    address to;
    uint256 amount;
    uint256 timestamp;
    bytes32 txHash;
  }

  //レシートの価値計算に使われる要素はこっちに残す
  struct Parameter {
    uint256 fromReceipt;
    uint256 toReceipt;
    uint256 fromBimboGummy;
    uint256 toBimboGummy;
    uint256 fromRank;
    uint256 toRank;
    uint256 amountBimboGummy;
    bool isBlueReceipt;
  }

  Ranking private ranking;
  //トークンID=>各記録
  mapping (uint256 => TransferRecord) private transferRecords;
  mapping(uint256 => Parameter) private parameters;
  //TransferRecord public transferRecord;

  event DebugEvent(string _text, address _address, bytes32 _txHash);  

  constructor( address _rankingAddress ) ERC721("Receipt", "RCPT") {

    require(_rankingAddress != address(0), "Invalid ranking address");
    ranking = Ranking(_rankingAddress);
  }

  function getTime() public view returns (uint256) {
    return block.timestamp;
  }

  function isTimePassed(uint256 _startTime, uint256 _duration ) public view returns (bool) {
    return block.timestamp >= _startTime + _duration;
  }

  function mint (
        address recipient,
        address _from,
        address _to,
        uint256 _amount,
        uint256 _bimboBalanceOfFrom,
        uint256 _bimboBalanceOfTo,
        bytes32 _txHash,
        bool _isBlueReceipt

    ) external returns ( uint256 ) {
        uint256 newTokenId = uint256(_txHash);
        emit DebugEvent("recipient address:", recipient, _txHash);
        _mint(recipient, newTokenId);//青レシートの場合はrecipientにfromアドレスが、赤レシートの場合はrecipientにtoアドレスが格納される
        uint256 _fromRank = ranking.getPlayerRank(_from);
        uint256 _toRank = ranking.getPlayerRank(_to);
        transferRecords[newTokenId] = TransferRecord({
            from: _from,
            to: _to,
            amount: _amount,
            timestamp: block.timestamp,
            txHash: _txHash
        });

        parameters[newTokenId] = Parameter({
            fromReceipt: balanceOf(_from),//ここを一週間という期間内に発行されたチケットに限定する
            toReceipt: balanceOf(_to),//ここを一週間という期間内に発行されたチケットに限定する
            fromBimboGummy: _bimboBalanceOfFrom,
            toBimboGummy: _bimboBalanceOfTo,
            fromRank: _fromRank,
            toRank: _toRank,
            amountBimboGummy: 0,
            isBlueReceipt : _isBlueReceipt
        });
        //青レシートか赤レシートかで入る値が変わる
        //青レシートの時…from→toの攻撃でfromに発行されてる。recipient(from)に0~4(toRank)
        //赤レシートの時…from→toの攻撃でtoに発行されている。recipient(to)に6~9(fromRank+5)
        if (_isBlueReceipt){
          ranking.updateBattleResult(recipient,_toRank);
        }else{
          ranking.updateBattleResult(recipient,_fromRank + 5);
        }
        //ここで緑レシートの概念的発行とrecipientのランクスコアの更新を行う

        return newTokenId;
  }

  function getTransactionRecord(uint256 tokenId) private view returns (TransferRecord memory) {
      return transferRecords[tokenId];

  }

  function getTimeStamp(uint256 tokenId) public view returns (uint256) {
      return transferRecords[tokenId].timestamp;
  }

  function getParameter( uint256 tokenId ) private view returns (Parameter memory) {

    return parameters[tokenId];  
  }
  function getReceiptSub(uint256 tokenId) public view returns (uint256) {
    uint256 a = getParameter(tokenId).fromReceipt;
    uint256 b = getParameter(tokenId).toReceipt;
    bool IsTo = getTransactionRecord(tokenId).to == msg.sender;
    bool IsFrom = getTransactionRecord(tokenId).from == msg.sender;
    if(!(IsTo || IsFrom)){
      return 1;
    }
    if (b - a > 0){//標的の方が期間内レシートを多く持っている
      return b - a + 1;
    }else{//標的より攻撃側の方が期間内レシートを多く持ってしまっている
      return 1;
    }
  }

}

